import frappe

@frappe.whitelist(methods=['POST'])
def create_instrument_profile(player_name: str, instrument_serial: str, customer: str, notes: str | None=None):
    if not player_name or not instrument_serial or not customer:
        frappe.throw("Missing required fields.")
    doc = frappe.get_doc({
        "doctype": "Instrument Profile",
        "player_name": player_name,
        "instrument_serial": instrument_serial,
        "customer": customer,
        "notes": notes or ""
    }).insert(ignore_permissions=True)
    frappe.db.commit()
    return {"name": doc.name}

