import hmac, hashlib, frappe

@frappe.whitelist(allow_guest=True, methods=['POST'])
def incoming():
    secret = frappe.conf.get("my_app_webhook_secret")
    if not secret:
        frappe.throw("Webhook secret not configured.")
    sig = frappe.get_request_header("X-MyApp-Signature") or ""
    raw = frappe.request.data or b""
    good = hmac.new(secret.encode(), raw, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, good):
        frappe.throw("Invalid signature.")
    # process payload
    payload = frappe.parse_json(frappe.request.data)
    frappe.logger().info({"webhook_received": payload})
    return {"ok": True}

